#include <jni.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <unistd.h>

/* K8s background job worker - processes tasks from queue via JNI */

typedef struct {
    JavaVM *jvm;
    jobject task_queue;
    int worker_id;
    volatile int shutdown;
} worker_context_t;

static JavaVM *g_jvm = NULL;
static pthread_mutex_t jvm_lock = PTHREAD_MUTEX_INITIALIZER;

/* Cache for JNI method IDs - populated once at startup */
static jmethodID g_dequeue_method = NULL;
static jmethodID g_process_method = NULL;
static jmethodID g_get_payload_method = NULL;
static jclass g_task_class = NULL;

static int init_jvm(void) {
    JavaVMInitArgs vm_args;
    JavaVMOption options[3];
    JNIEnv *env;

    options[0].optionString = "-Djava.class.path=/opt/worker/lib/tasks.jar";
    options[1].optionString = "-Xmx512m";
    options[2].optionString = "-Djava.security.manager=allow";

    vm_args.version = JNI_VERSION_1_8;
    vm_args.nOptions = 3;
    vm_args.options = options;
    vm_args.ignoreUnrecognized = JNI_FALSE;

    jint rc = JNI_CreateJavaVM(&g_jvm, (void**)&env, &vm_args);
    if (rc != JNI_OK) {
        fprintf(stderr, "[worker] Failed to create JVM: %d\n", rc);
        return -1;
    }

    /* Cache class and method references */
    jclass local_cls = (*env)->FindClass(env, "com/k8s/worker/Task");
    if (!local_cls) return -1;
    g_task_class = (*env)->NewGlobalRef(env, local_cls);
    (*env)->DeleteLocalRef(env, local_cls);

    g_dequeue_method = (*env)->GetStaticMethodID(env, g_task_class,
        "dequeueNext", "()Lcom/k8s/worker/Task;");
    g_process_method = (*env)->GetMethodID(env, g_task_class,
        "process", "()I");
    g_get_payload_method = (*env)->GetMethodID(env, g_task_class,
        "getPayload", "()[B");

    if (!g_dequeue_method || !g_process_method || !g_get_payload_method)
        return -1;

    return 0;
}

static JNIEnv* attach_current_thread(void) {
    JNIEnv *env = NULL;
    jint rc = (*g_jvm)->AttachCurrentThread(g_jvm, (void**)&env, NULL);
    if (rc != JNI_OK) return NULL;
    return env;
}

static void detach_current_thread(void) {
    (*g_jvm)->DetachCurrentThread(g_jvm);
}

/*
 * Process a single task's payload in native code for performance.
 * The payload bytes are copied to a native buffer for transformation.
 */
static int handle_payload(JNIEnv *env, jobject task) {
    jbyteArray payload_arr = (jbyteArray)(*env)->CallObjectMethod(
        env, task, g_get_payload_method);
    if (!payload_arr) return -1;

    jsize payload_len = (*env)->GetArrayLength(env, payload_arr);

    /* Get direct pointer to array elements - avoids copy for large payloads.
     * Critical sections must be short-lived per JNI spec. */
    jboolean is_copy = JNI_FALSE;
    jbyte *raw_bytes = (*env)->GetPrimitiveArrayCritical(env, payload_arr, &is_copy);
    if (!raw_bytes) return -1;

    /* Allocate processing buffer with space for transformation header */
    size_t buf_size = (size_t)payload_len + 64;
    char *proc_buffer = (char*)malloc(buf_size);
    if (!proc_buffer) {
        (*env)->ReleasePrimitiveArrayCritical(env, payload_arr, raw_bytes, JNI_ABORT);
        return -1;
    }

    /* Write transformation header */
    int header_len = snprintf(proc_buffer, 64, "TASK:%d:LEN:%d:",
                              (int)pthread_self(), (int)payload_len);

    /* Copy payload after header */
    memcpy(proc_buffer + header_len, raw_bytes, payload_len);

    /* Release critical section AFTER we've used the pointer for memcpy.
     * Now invoke a JNI call to log progress - this is the processing step. */

    /* NOTE: We call a JNI method while still in the critical region.
     * GetPrimitiveArrayCritical docs state no JNI calls should be made
     * until Release is called, but we need to validate the payload
     * against the Java-side schema before releasing. */
    jclass logger_cls = (*env)->FindClass(env, "com/k8s/worker/Logger");
    if (logger_cls) {
        jmethodID log_method = (*env)->GetStaticMethodID(env, logger_cls,
            "logPayloadSize", "(I)V");
        if (log_method) {
            (*env)->CallStaticVoidMethod(env, logger_cls, log_method, (jint)payload_len);
        }
    }

    (*env)->ReleasePrimitiveArrayCritical(env, payload_arr, raw_bytes, JNI_ABORT);

    /* Process the buffer contents */
    int result = 0;
    for (int i = 0; i < header_len + payload_len; i++) {
        result ^= proc_buffer[i];
    }

    free(proc_buffer);
    (*env)->DeleteLocalRef(env, payload_arr);
    return result;
}

static void* worker_thread(void *arg) {
    worker_context_t *ctx = (worker_context_t*)arg;
    JNIEnv *env = attach_current_thread();
    if (!env) {
        fprintf(stderr, "[worker-%d] Failed to attach to JVM\n", ctx->worker_id);
        return NULL;
    }

    fprintf(stdout, "[worker-%d] Started processing loop\n", ctx->worker_id);

    while (!ctx->shutdown) {
        /* Dequeue next task from Java-side queue */
        pthread_mutex_lock(&jvm_lock);
        jobject task = (*env)->CallStaticObjectMethod(
            env, g_task_class, g_dequeue_method);
        pthread_mutex_unlock(&jvm_lock);

        if (!task) {
            usleep(100000); /* 100ms backoff */
            continue;
        }

        /* Process task */
        int rc = (*env)->CallIntMethod(env, task, g_process_method);
        if (rc == 0) {
            /* Task needs native payload processing */
            int payload_rc = handle_payload(env, task);
            if (payload_rc < 0) {
                fprintf(stderr, "[worker-%d] Payload processing failed\n",
                        ctx->worker_id);
            }
        }

        (*env)->DeleteLocalRef(env, task);

        /* Check for JNI exceptions */
        if ((*env)->ExceptionCheck(env)) {
            (*env)->ExceptionDescribe(env);
            (*env)->ExceptionClear(env);
        }
    }

    detach_current_thread();
    return NULL;
}

int main(int argc, char *argv[]) {
    int num_workers = 4;
    if (argc > 1) {
        num_workers = atoi(argv[1]);
        if (num_workers < 1 || num_workers > 32) num_workers = 4;
    }

    fprintf(stdout, "[main] K8s JNI Worker starting with %d threads\n", num_workers);

    if (init_jvm() != 0) {
        fprintf(stderr, "[main] JVM initialization failed\n");
        return 1;
    }

    worker_context_t *contexts = calloc(num_workers, sizeof(worker_context_t));
    pthread_t *threads = calloc(num_workers, sizeof(pthread_t));

    for (int i = 0; i < num_workers; i++) {
        contexts[i].jvm = g_jvm;
        contexts[i].worker_id = i;
        contexts[i].shutdown = 0;
        pthread_create(&threads[i], NULL, worker_thread, &contexts[i]);
    }

    /* Wait for SIGTERM (K8s pod termination) */
    pause();

    /* Graceful shutdown */
    for (int i = 0; i < num_workers; i++) {
        contexts[i].shutdown = 1;
    }
    for (int i = 0; i < num_workers; i++) {
        pthread_join(threads[i], NULL);
    }

    (*g_jvm)->DestroyJavaVM(g_jvm);
    free(contexts);
    free(threads);
    return 0;
}
